  const PRE_UPDATE_KEY = 'phrase-sprint-backup-before-supplements-v1';
  let persistenceBlocked = false;
  let storageIssue = '';

  function isRetiredSupplementSentence(word) {
    return (['S1','S2'].includes(word.group) && word.quiz?.kind==='sentence') || /^S[12]-.+-sentence$/.test(String(word.number));
  }

  function mergeStoredState(saved) {
    const previousWords = Array.isArray(saved?.words) ? saved.words.map(normalizeWord) : [];
    const old = previousWords.filter(w=>!isRetiredSupplementSentence(w));
    const retiredSupplementQuestions = [...new Map([
      ...(Array.isArray(saved?.retiredSupplementQuestions)?saved.retiredSupplementQuestions:[]),
      ...previousWords.filter(isRetiredSupplementSentence)
    ].map(w=>[w.number,w])).values()];
    const byNumber = new Map(old.map(w => [w.number, w]));
    const catalog = [...DEMO_WORDS, ...SUPPLEMENT_CATALOG].map(normalizeWord);
    const numbers = new Set(catalog.map(w => w.number));
    const words = catalog.map(w => {
      const previous = byNumber.get(w.number);
      return previous ? {...previous, ...w, id:previous.id, progress:previous.progress, note:previous.note, createdAt:previous.createdAt} : w;
    });
    words.push(...old.filter(w => !numbers.has(w.number)));
    return {...saved, version:1, catalogVersion:CATALOG_VERSION, words, retiredSupplementQuestions, activity:saved?.activity || {}, settings:{autoAudio:true,listeningOnly:false,rate:0.85,...saved?.settings}};
  }

  function loadState() {
    let saved = null;
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw !== null) {
        saved = JSON.parse(raw);
        if (saved?.version !== 1 || !Array.isArray(saved.words)) throw new Error('履歴の形式を確認できません');
        if (!localStorage.getItem(PRE_UPDATE_KEY)) {
          localStorage.setItem(PRE_UPDATE_KEY, raw);
          if (localStorage.getItem(PRE_UPDATE_KEY) !== raw) throw new Error('更新前の履歴を保管できません');
        }
      }
    } catch (e) {
      persistenceBlocked = true;
      storageIssue = '履歴の読み込み・保存に問題があります。元の保存内容を保護するため、この画面の回答は保存しません。データ管理からバックアップを保存してください。';
      console.warn(e);
    }
    return mergeStoredState(saved);
  }

  function saveState() {
    if (persistenceBlocked) return false;
    try {localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); return true;}
    catch (e) {
      persistenceBlocked = true;
      storageIssue = '端末に学習履歴を保存できません。データ管理から現在の履歴を保存してください。';
      for(const id of ['storage-issue','global-storage-issue']){const b=document.getElementById(id);if(b){b.textContent=storageIssue;b.hidden=false;}}
      return false;
    }
  }

  function isSupplementWordCard(word) {
    return ['S1','S2'].includes(word.group);
  }

